// Small Rocq programs that exercise every accepted construct and every error
// of the Rocq frontend (js/src/translation/rocq.js), keyed name → [source
// extension, source text], so the Rust frontend can be compared with the
// JavaScript one case by case at the parse stage.

const rocqHead = 'From Stdlib Require Import NArith ZArith String Lia.\nOpen Scope string_scope.\n';
const rocqTree = 'Inductive Tree : Type :=\n| leaf : Tree\n| node : Tree -> nat -> Tree -> Tree.\n';
const main = 'Definition main : list string := ["x"].\n';
const v = (text) => ['v', `${rocqHead}${text}\n`];
const thm = (statement, proof, end = 'Qed') => v(`Theorem t ${statement}.\nProof.\n${proof}\n${end}.`);
const fn = (signature, body) => v(`Definition f ${signature} :=\n  ${body}.`);

